// Тикет #6a86f7ee5747 «פיתוח: מדור ברכות» (F-93), проверен 07.10.2026 → עבר QA (session.json: «соответствует F-93 (с решениями 22.09, 06.10)»).
// Опора: F-93 AC4 «פריט הברכות בניווט התחתון מוביל למשטח שקיים בפועל ולא למסך ריק»; решение владельца 22.09 (список, поиск, фильтр по נוסח профиля);
// реджект 27.09 п.3 (на экране ברכה нет יחיד/מניין; у одно-קטעной ברכה нет «קודם» и «1 מתוך 1»; кнопка «חזרה לברכות», не «סיים תפילה»).
// Скрины: ee5747-1-list-ashkenaz-11 / ee5747-1-list-sfarad-12 («הברכות מוצגות בנוסח אשכנז שנשמר בפרופיל.»), ee5747-2-search-gefen,
// ee5747-3-mezonot-screen-unapproved (экран ברכה: «חזרה לברכות», без элементов молитвы).
// שהחיינו в אשכנז нет — в документации нет, не проверяем. Только просмотр.
import { expect } from '@wdio/globals';
import { byText, byTextMatches, tapText, expectVisibleText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { typeSearch, searchField, shown } from '../_lib/app-0710.ts';

const NUSACH_NOTE = 'הברכות מוצגות בנוסח (אשכנז|ספרד) שנשמר בפרופיל\\.?';

describe('מדור ברכות', () => {
  afterEach(async () => {
    if (await shown(searchField())) await typeSearch('');
    await toHome();
  });

  it('BR-01 «ברכות» → список и строка נוסח, поиск «גפן», экран ברכה без элементов молитвы, «חזרה לברכות» #6a86f7ee5747 @prod-safe', async () => {
    // 1. Нижняя навигация «ברכות» → экран со списком (не пустой) и строкой «הברכות מוצגות בנוסח … שנשמר בפרופיל.».
    await goTab('ברכות');
    await (await searchField()).waitForDisplayed({ timeout: 20000 });
    await expect(byTextMatches(NUSACH_NOTE)).toBeDisplayed();
    for (const name of ['נטילת ידים והמוציא', 'בורא מיני מזונות', 'בורא פרי הגפן', 'בורא פרי העץ']) {
      await expectVisibleText(name);
    }

    // 2. Поиск «גפן» → только «בורא פרי הגפן»; строка נוסח остаётся.
    await typeSearch('גפן');
    await expectVisibleText('בורא פרי הגפן');
    await expect(byText('בורא פרי העץ')).not.toBeDisplayed();
    await expect(byText('בורא מיני מזונות')).not.toBeDisplayed();
    await expect(byTextMatches(NUSACH_NOTE)).toBeDisplayed();

    // 3. Открыть «בורא פרי הגפן» → экран ברכה: заголовок с נוסח, «חזרה לברכות»; нет יחיד/מניין, «קודם», «N מתוך M», «סיים תפילה».
    await tapText('בורא פרי הגפן');
    await expect(byTextMatches('(?s)בורא פרי הגפן.*\\((אשכנזי|ספרדי)\\)')).toBeDisplayed();
    await expectVisibleText('חזרה לברכות');
    for (const absent of ['יחיד', 'מניין', 'קודם', 'סיים תפילה']) {
      await expect(byText(absent)).not.toBeDisplayed();
    }
    await expect(byTextMatches('\\d+ מתוך \\d+')).not.toBeDisplayed();
    await expect(byText('1 מתוך 1')).not.toBeDisplayed();

    // 4. «חזרה לברכות» → снова список со строкой נוסח.
    await tapText('חזרה לברכות');
    await (await searchField()).waitForDisplayed();
    await expect(byTextMatches(NUSACH_NOTE)).toBeDisplayed();
  });
});
